#ifndef VITA_NATIVE_INSTALL_PLATFORM_H
#define VITA_NATIVE_INSTALL_PLATFORM_H
#include <stddef.h>
#include <stdint.h>

/* All relative paths are generated by the service from fixed names, indices,
   build IDs and lowercase hex attempts. No API receives a user path. */
int nip_init(void);
int nip_mkdir(const char *relative); /* 0 created, 1 existing directory, -1 error */
int nip_kind(const char *relative,uint64_t *bytes); /* 0 absent,1 regular,2 directory,-1 error */
int nip_open_read(const char *relative);
int nip_open_new(const char *relative);
int nip_read(int fd,void *out,size_t bytes);
int nip_write(int fd,const void *data,size_t bytes);
int nip_size(int fd,uint64_t *bytes);
int nip_sync(int fd);
int nip_close(int fd);
int nip_sync_device(void);
int nip_rename_new(const char *from,const char *to);
int nip_list(const char *relative,unsigned index,char out[64]); /*1 entry,0 EOF,-1 error; excludes dot */
int nip_free(uint64_t *bytes);
int nip_installed_open(unsigned index); /* fixed owned NI_TITLE only */
int nip_installed_kind(void); /*0 absent,2 directory,-1 otherwise */
int nip_promote_available(int *paf_result,int *promoter_result);
/* Explicit install only. Never used by init/recovery. PAF must already exist;
   refuse borrowed PromoterUtil. A submission error may have effects. */
int nip_promote_start(const char *relative,uint64_t issued,uint64_t expires,
                      int *invoked,int *cleanup_result);
int nip_promote_poll(int *state,int *result); /*0 observed, -1 unknown; state0 final*/
int nip_promote_finish(void); /* only after confirmed final state */
#ifndef __vita__
void nip_host_root(const char *root);
void nip_host_fault(const char *name,int value);
unsigned nip_host_submissions(void);
#endif
#endif
